def add_abs(a, b):
    i, j = len(a) - 1, len(b) - 1
    carry = 0
    out = []
    while i >= 0 or j >= 0 or carry:
        s = carry
        if i >= 0:
            s += ord(a[i]) - 48
            i -= 1
        if j >= 0:
            s += ord(b[j]) - 48
            j -= 1
        out.append(chr(48 + s % 10))
        carry = s // 10
    return ''.join(reversed(out))

def sub_abs(a, b):
    i, j = len(a) - 1, len(b) - 1
    borrow = 0
    out = []
    while i >= 0:
        x = ord(a[i]) - 48 - borrow
        if j >= 0:
            x -= ord(b[j]) - 48
            j -= 1
        if x < 0:
            x += 10
            borrow = 1
        else:
            borrow = 0
        out.append(chr(48 + x))
        i -= 1
    while len(out) > 1 and out[-1] == '0':
        out.pop()
    return ''.join(reversed(out))

def cmp_abs(a, b):
    if len(a) != len(b):
        return 1 if len(a) > len(b) else -1
    return (a > b) - (a < b)

