def valid(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    if not (1 <= len(local) <= 64):
        return False
    if local[0] == "." or local[-1] == "." or ".." in local:
        return False
    for c in local:
        if not ("a" <= c <= "z" or "0" <= c <= "9" or c == "." or c == "_"):
            return False
    parts = domain.split(".")
    if len(parts) < 2:
        return False
    for p in parts:
        if not (1 <= len(p) <= 63):
            return False
        for c in p:
            if not ("a" <= c <= "z" or "0" <= c <= "9"):
                return False
    last = parts[-1]
    if not (2 <= len(last) <= 6):
        return False
    for c in last:
        if not ("a" <= c <= "z"):
