import sys

def apply(nums, ops):
    b = nums.pop()
    a = nums.pop()
    op = ops.pop()
    if op == "+":
        nums.append(a + b)
    elif op == "-":
        nums.append(a - b)
    else:
        nums.append(a * b)

def main():
    s = sys.stdin.readline().strip()
    nums = []
    ops = []
    prec = {"+": 1, "-": 1, "*": 2}
    i = 0
    while i < len(s):
        c = s[i]
        if c == " ":
            i += 1
        elif "0" <= c <= "9":
            num = 0
            while i < len(s) and "0" <= s[i] <= "9":
                num = num * 10 + int(s[i])
                i += 1
            nums.append(num)
        elif c == "(":
            ops.append(c)
            i += 1
        elif c == ")":
            while ops[-1] != "(":
                apply(nums, ops)
            ops.pop()
            i += 1
        else:
            while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[c]:
                apply(nums, ops)
            ops.append(c)
            i += 1
    while ops:
        apply(nums, ops)
    print(nums[0])

main()

